/** Safe text-only renderer; route labels are generated by Transbora.
 * Legacy compact labels still display unchanged. No innerHTML for GTFS data.
 */
export function appendReadableRoute(parent,label){
  const text=String(label||'');
  const pieces=text.split(' | ').map(x=>x.trim()).filter(Boolean);
  if(pieces.length<5||!pieces.some(x=>x.startsWith('Départ :'))){
    parent.textContent=text;
    return;
  }
  parent.replaceChildren();
  for(let i=0;i<pieces.length;i++){
    const piece=pieces[i];
    const className=i===0?'choice-index':
      i===1?'choice-operator':
      i===2?'choice-times':
      piece.startsWith('Départ :')||piece.startsWith('Arrivée :')?'choice-station':
      piece.startsWith('⚠')?'choice-warning':'choice-detail';
    const node=document.createElement('span');node.className=className;
    node.textContent=piece;parent.append(node);
  }
}
